-- Repair / rebuild career-skill mappings for the current v2 schema
-- This fixes duplicate career mappings caused by matching career name alone.
-- It does NOT delete careers, domains, skills, education, or resume data.

USE `ai_skill_gap`;

-- Add canonical skills used by the analyzer if they do not already exist.

-- Rebuild only the v2 career-skill junction table.
DELETE FROM career_skill_requirements;



-- =====================================================
-- VERIFICATION
-- =====================================================
SELECT COUNT(*) AS career_skill_requirements_count
FROM career_skill_requirements;

SELECT
    c.id AS career_id,
    d.name AS domain,
    c.name AS career,
    s.name AS skill,
    csr.required_level
FROM career_skill_requirements csr
JOIN careers_v2 c ON c.id = csr.career_id
JOIN domains d ON d.id = c.domain_id
JOIN skills_v2 s ON s.id = csr.skill_id
WHERE c.name = 'Data Scientist'
ORDER BY csr.required_level DESC, s.name;
